using System;
using System.Collections.Generic;
using System.Linq;
using CargoWiseOne.ResourceStrings;
using Enterprise.Core;
using Enterprise.ZArchitecture.Core;
using Enterprise.ZArchitecture.Environment.Testing;
using NUnit.Framework;

namespace Enterprise.Registry.Business.Testing
{
	[TestedType(typeof(IncoTermChargeCodesRegistryDataType))]
	sealed class IncoTermChargeCodesRegistryDataTypeTest : NonPersistentBusinessObjectRegistryDataTypeTestCase<IncoTermChargeCodesRegistryDataType>
	{
		#region Implementation

		protected override IncoTermChargeCodesRegistryDataType GetNewDataType()
		{
			return new IncoTermChargeCodesRegistryDataType();
		}

		protected override string ExpectedEditorName
		{
			get { return "IncotermsRegistryItemEditor"; }
		}

		public void TestTranslatable()
		{
			foreach (KeyValuePair<string, MultilingualString> incoTermValue in Constants.IncoTerms.Descriptions.DefaultCodeDescriptionPairs)
			{
				if (new List<string>() { Constants.IncoTerms.FreeCarrier, Constants.IncoTerms.FreeCarrierBuyer, Constants.IncoTerms.FreeCarrierSeller }.Contains(incoTermValue.Value))
				{
					TestTranslatable_ForValueCanEditLocalLanguageValue(incoTermValue);
				}
				else if (RatingDataRegistry.Instance.IncoTermDefinition.Value.Any(item => ((IncoTermChargeCodes)item).IncoTerm == incoTermValue.Key))
				{
					TestTranslatable_ForValueCannotEditLocalLanguageValue(incoTermValue);
				}
			}
		}

		public void TestTranslatable_ForValueCanEditLocalLanguageValue(KeyValuePair<string, MultilingualString> incoTermValue)
		{
			var defaultDescription = RatingDataRegistry.Instance.IncoTermDefinition.Value.First(item => ((IncoTermChargeCodes)item).IncoTerm == incoTermValue.Key);
			AssertEquals("Default Description", incoTermValue.Value, ((IncoTermChargeCodes)defaultDescription).IncoTermDescriptionMultilingual.ToString(SharedConstants.Languages.Indonesian));

			using (var mockChs = Res.GetLanguageInstance(SharedConstants.Languages.ChineseSimplified).UseMockData())
			{
				string key = ((ResourceString)((IncoTermChargeCodes)defaultDescription).IncoTermDescriptionMultilingual).ResourceKey;
				mockChs.Put(key, new ResourceStringData(key, "Translate to ZH-CN"));

				var defaultDescriptionTranslated = RatingDataRegistry.Instance.IncoTermDefinition.Value.First(item => ((IncoTermChargeCodes)item).IncoTerm == incoTermValue.Key);
				AssertEquals("Default Description should be Translate", "Translate to ZH-CN", ((IncoTermChargeCodes)defaultDescriptionTranslated).IncoTermDescriptionMultilingual.ToString(SharedConstants.Languages.ChineseSimplified));
				AssertEquals("English Description should not be Translate", incoTermValue.Value, ((IncoTermChargeCodes)defaultDescriptionTranslated).EnglishIncoTermDescription);
			}

			var incoTermDefinitions = new IncoTermChargeCodesCollection();
			var def = incoTermDefinitions.AddNew();
			def.IncoTerm = incoTermValue.Key;
			def.IncoTermDescription = "Override Description";
			def.Origin = Constants.PaymentParty.Consignee;
			def.Loading = Constants.PaymentParty.Consignee;
			def.Freight = Constants.PaymentParty.Consignee;
			def.Insurance = Constants.PaymentParty.Consignee;
			def.Unloading = Constants.PaymentParty.Consignee;
			def.Destination = Constants.PaymentParty.Consignee;
			def.Brokerage = Constants.PaymentParty.Consignee;
			def.CustomsDuty = Constants.PaymentParty.Consignee;
			def.OriginBrokerage = Constants.PaymentParty.Consignee;

			using (RatingDataRegistry.Instance.IncoTermDefinition.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, incoTermDefinitions))
			{
				var overrideDescription = RatingDataRegistry.Instance.IncoTermDefinition.Value.First(item => ((IncoTermChargeCodes)item).IncoTerm == incoTermValue.Key);
				AssertEquals("Override Description", "Override Description", ((IncoTermChargeCodes)overrideDescription).IncoTermDescriptionMultilingual.ToString(SharedConstants.Languages.Indonesian));

				using (var mockChs = Res.GetLanguageInstance(SharedConstants.Languages.Indonesian).UseMockData())
				{
					string key = ((ResourceString)((IncoTermChargeCodes)overrideDescription).IncoTermDescriptionMultilingual).ResourceKey;
					mockChs.Put(key, new ResourceStringData(key, "Override Description Translate to ID-ID"));

					var overrideDescriptionTranslated = RatingDataRegistry.Instance.IncoTermDefinition.Value.First(item => ((IncoTermChargeCodes)item).IncoTerm == incoTermValue.Key);
					AssertEquals("Override Description should be Translate", "Override Description Translate to ID-ID", ((IncoTermChargeCodes)overrideDescriptionTranslated).IncoTermDescriptionMultilingual.ToString(SharedConstants.Languages.Indonesian));
					AssertEquals("English Description should not be Translate", "Override Description", ((IncoTermChargeCodes)overrideDescriptionTranslated).EnglishIncoTermDescription);
				}
			}
		}

		public void TestTranslatable_ForValueCannotEditLocalLanguageValue(KeyValuePair<string, MultilingualString> incoTermValue)
		{
			var defaultDescription = RatingDataRegistry.Instance.IncoTermDefinition.Value.First(item => ((IncoTermChargeCodes)item).IncoTerm == incoTermValue.Key);
			AssertEquals("Default Description", incoTermValue.Value, ((IncoTermChargeCodes)defaultDescription).IncoTermDescriptionMultilingual.ToString(SharedConstants.Languages.Indonesian));

			using (var mockChs = Res.GetLanguageInstance(SharedConstants.Languages.ChineseSimplified).UseMockData())
			{
				string key = ((ResourceString)Constants.IncoTerms.Descriptions.ExWorks).ResourceKey;
				mockChs.Put(key, new ResourceStringData(key, "EXW - ZH-CN"));

				var defaultDescriptionTranslated = RatingDataRegistry.Instance.IncoTermDefinition.Value.First(item => ((IncoTermChargeCodes)item).IncoTerm == incoTermValue.Key);
				AssertEquals("Default Description should not be Translate", incoTermValue.Value, ((IncoTermChargeCodes)defaultDescriptionTranslated).IncoTermDescriptionMultilingual.ToString(SharedConstants.Languages.ChineseSimplified));
				AssertEquals("English Description should not be Translate", incoTermValue.Value, ((IncoTermChargeCodes)defaultDescriptionTranslated).EnglishIncoTermDescription);
			}
		}

